package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Immutable, private attachment snapshots. The original filename is kept inside a unique directory. */
@Component public class LegacyFinanceMailFiles {
 private final Path root;public LegacyFinanceMailFiles(@Value("${app.pdf.storage-path}")String root){this.root=Path.of(root).toAbsolutePath().normalize();}
 static String filename(String title){if(title==null||title.contains("/")||title.contains("\\")||title.chars().anyMatch(c->c<32||c==127)|| (title+".pdf").getBytes(StandardCharsets.UTF_8).length>255||title.length()+4>250)throw new BusinessException(400,"财务PDF文件名无效");return title+".pdf";}
 private void guard(Path path)throws Exception{Path current=path.getRoot();for(Path part:path){current=current.resolve(part);if(Files.isSymbolicLink(current))throw new BusinessException(409,"财务附件不能使用符号链接");}}
 private static String sha(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
 public Map<String,Object> save(String title,byte[] bytes){String filename=filename(title);if(bytes==null||bytes.length<5||bytes.length>20*1024*1024||!new String(bytes,0,5,StandardCharsets.US_ASCII).equals("%PDF-"))throw new BusinessException(409,"财务PDF输出无效");try{guard(root);Path parent=root.resolve("finance-mail");guard(parent);Files.createDirectories(parent);Path dir=Files.createDirectory(parent.resolve(UUID.randomUUID().toString()),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));Path target=dir.resolve(filename);Files.write(target,bytes,StandardOpenOption.CREATE_NEW);Files.setPosixFilePermissions(target,PosixFilePermissions.fromString("rw-------"));return Map.of("path",root.relativize(target).toString(),"filename",filename,"sha256",sha(bytes),"size",bytes.length);}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(409,"财务附件无法保存");}}
 private Path target(String relative)throws Exception{if(relative==null||!relative.matches("finance-mail/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[^/\\\\]+"))throw new BusinessException(409,"财务附件路径无效");Path target=root.resolve(relative).normalize();if(!target.startsWith(root))throw new BusinessException(409,"财务附件路径无效");guard(target);return target;}
 public byte[] read(Map<String,Object> metadata){try{Path target=target(Objects.toString(metadata.get("path"),null));if(!Files.isRegularFile(target,LinkOption.NOFOLLOW_LINKS)||Files.size(target)>20*1024*1024)throw new BusinessException(409,"财务附件缺失或过大");byte[] bytes=Files.readAllBytes(target);if(bytes.length<5||!new String(bytes,0,5,StandardCharsets.US_ASCII).equals("%PDF-")||!sha(bytes).equals(metadata.get("sha256")))throw new BusinessException(409,"财务附件已变化");return bytes;}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(409,"财务附件无法读取");}}
 void discardUnused(Map<String,Object> metadata){try{Path target=target(metadata.get("path").toString());Files.deleteIfExists(target);Files.deleteIfExists(target.getParent());}catch(Exception ignored){/* Keep private orphan rather than deleting a possibly committed attachment. */}}
}
